use xiom.io;
type Box[T] = {
  value: T;
}

fn Box.get_value[T](self) -> T {
  return self.value;
}

fn Box.set_value[T](self: &mut Box[T], new_value: T) {
  self.value = new_value;
}

fn main() -> Int {
  var int_box: Box[Int] = Box[Int]{ value: 100 };
  io.println(int_box.get_value().to_str());
  int_box.set_value(200);
  io.println(int_box.get_value().to_str());

  let str_box: Box[Str] = Box[Str]{ value: "XIOM" };
  io.println(str_box.get_value().to_str());
  return 0;
}
